    42  bool
    43  fill_txt(const char *src, size_t len, size_t olen)
    44  {
    45      char *dst;
    46      int h;
    47      debug_decl(fill_txt, SUDOERS_DEBUG_PARSER);
    48
    49      dst = olen ? realloc(sudoerslval.string, olen + len + 1) : malloc(len + 1);
    50      if (dst == NULL) {
    51          if (olen != 0) {
    52              /* realloc failure, avoid leaking original */
    53              free(sudoerslval.string);
    54              sudoerslval.string = NULL;
    55          }
    56          sudo_warnx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
    57          sudoerserror(NULL);
    58          debug_return_bool(false);
    59      }
    60      sudoerslval.string = dst;
    61
    62      /* Copy the string and collapse any escaped characters. */
    63      dst += olen;
    64      while (len--) {
    65          if (*src == '\\' && len) {
    66              if (src[1] == 'x' && len >= 3 && (h = hexchar(src + 2)) != -1) {
    67                  *dst++ = h;
    68                  src += 4;
    69                  len -= 3;
    70              } else {
    71                  src++;
    72                  len--;
    73                  *dst++ = *src++;
    74              }
    75          } else {
    76              *dst++ = *src++;
    77          }
    78      }
    79      *dst = '\0';
    80      debug_return_bool(true);
    81  }
