    98  bool
    99  fill_cmnd(const char *src, size_t len)
   100  {
   101      char *dst;
   102      size_t i;
   103      debug_decl(fill_cmnd, SUDOERS_DEBUG_PARSER);
   104
   105      arg_len = arg_size = 0;
   106
   107      dst = sudoerslval.command.cmnd = malloc(len + 1);
   108      if (dst == NULL) {
   109          sudo_warnx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
   110          sudoerserror(NULL);
   111          debug_return_bool(false);
   112      }
   113      sudoerslval.command.args = NULL;
   114
   115      /* Copy the string and collapse any escaped sudo-specific characters. */
   116      for (i = 0; i < len; i++) {
   117          if (src[i] == '\\' && i != len - 1 && SPECIAL(src[i + 1]))
   118              *dst++ = src[++i];
   119          else
   120              *dst++ = src[i];
   121      }
   122      *dst = '\0';
   123
   124      /* Check for sudoedit specified as a fully-qualified path. */
   125      if ((dst = strrchr(sudoerslval.command.cmnd, '/')) != NULL) { // -V575
   126          if (strcmp(dst, "/sudoedit") == 0) {
   127              if (sudoers_strict) {
   128                  sudoerserror(
   129                      N_("sudoedit should not be specified with a path"));
   130              }
   131              free(sudoerslval.command.cmnd);
   132              if ((sudoerslval.command.cmnd = strdup("sudoedit")) == NULL) {
   133                  sudo_warnx(U_("%s: %s"), __func__,
   134                      U_("unable to allocate memory"));
   135                  debug_return_bool(false);
   136              }
   137          }
   138      }
   139
   140      debug_return_bool(true);
   141  }
