   143  bool
   144  fill_args(const char *s, size_t len, int addspace)
   145  {
   146      unsigned int new_len;
   147      char *p;
   148      debug_decl(fill_args, SUDOERS_DEBUG_PARSER);
   149
   150      if (arg_size == 0) {
   151          addspace = 0;
   152          new_len = len;
   153      } else
   154          new_len = arg_len + len + addspace;
   155
   156      if (new_len >= arg_size) {
   157          /* Allocate in increments of 128 bytes to avoid excessive realloc(). */
   158          arg_size = (new_len + 1 + 127) & ~127;
   159
   160          p = realloc(sudoerslval.command.args, arg_size);
   161          if (p == NULL) {
   162              sudo_warnx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
   163              goto bad;
   164          }
   165          sudoerslval.command.args = p;
   166      }
   167
   168      /* Efficiently append the arg (with a leading space if needed). */
   169      p = sudoerslval.command.args + arg_len;
   170      if (addspace)
   171          *p++ = ' ';
   172      len = arg_size - (p - sudoerslval.command.args);
   173      if (strlcpy(p, s, len) >= len) {
   174          sudo_warnx(U_("internal error, %s overflow"), __func__);
   175          goto bad;
   176      }
   177      arg_len = new_len;
   178      debug_return_bool(true);
   179  bad:
   180      sudoerserror(NULL);
   181      free(sudoerslval.command.args);
   182      sudoerslval.command.args = NULL;
   183      arg_len = arg_size = 0;
   184      debug_return_bool(false);
   185  }
