   187  /*
   188   * Check to make sure an IPv6 address does not contain multiple instances
   189   * of the string "::".  Assumes strlen(s) >= 1.
   190   * Returns true if address is valid else false.
   191   */
   192  bool
   193  ipv6_valid(const char *s)
   194  {
   195      int nmatch = 0;
   196      debug_decl(ipv6_valid, SUDOERS_DEBUG_PARSER);
   197
   198      for (; *s != '\0'; s++) {
   199          if (s[0] == ':' && s[1] == ':') {
   200              if (++nmatch > 1)
   201                  break;
   202          }
   203          if (s[0] == '/')
   204              nmatch = 0;                 /* reset if we hit netmask */
   205      }
   206
   207      debug_return_bool(nmatch <= 1);
   208  }
